"""Six bounded, source-linked explainers; no generated model facts or scoring."""
import html
def field(key,label,minimum=0,maximum=2000000,step='any'):
 return f'<label>{html.escape(label)}<input name="{key}" type="number" min="{minimum}" max="{maximum}" step="{step}" required></label>'
def guide_visual(slug):
 if slug in ('used-car-ownership-budget','hybrid-fuel-break-even'):
  cost=slug=='used-car-ownership-budget'
  fields=(field('price','Purchase, upfront taxes and fees (USD)')+field('resale','Assumed net resale (USD)')+field('years','Holding period (years)',1,20)+field('insurance','Insurance quote per year (USD)')+field('maintenance','Maintenance and recurring fees per year (USD)')+field('reserve','Assumed repair spending per year (USD)')+field('mpg','Fuel economy (US MPG)',1,200)) if cost else (field('a','Candidate A fuel economy (US MPG)',1,200)+field('b','Candidate B fuel economy (US MPG)',1,200)+field('premium','Candidate B extra upfront price (USD; may be negative)',-2000000))
  fields+=field('miles','Distance per year (miles)',0,200000)+field('fuel','Fuel price (USD per US gallon)',.01,30)
  return '<section class="guide-visual guide-tools" data-guide-calculator="'+('cost' if cost else 'fuel')+'"><h2>'+('Build your cash-cost breakdown' if cost else 'Calculate a fuel-only payback')+'</h2><p>Enter your own assumptions. These are US-unit cash scenarios. Entries stay in this page and are not saved.</p><form><div class="guide-fields">'+fields+'</div><button type="submit" class="btn">Calculate my scenario</button></form><div data-guide-result role="status" aria-live="polite"><p>Your result remains unknown until every input is supplied.</p></div><noscript><p>Use the formulas and fictional worked example in the article below; this form requires JavaScript.</p></noscript><p class="note">Source: your entries and the formulas explained below. No live quote or cost forecast. Research checked 10 November 2026.</p></section><script type="module" src="/assets/buying-explainers.mjs"></script>'
 if slug=='match-car-version-before-you-buy':
  return '<figure class="guide-visual"><figcaption><strong>Keep claims, evidence and scope separate.</strong></figcaption><ol class="guide-diagram"><li><b>Advert claim</b><span>Year, market, powertrain and drivetrain as described by the seller.</span></li><li><b>Vehicle evidence</b><span>Match documents and manufacturer-reported decoder fields; leave unclear details open.</span></li><li><b>Source scope</b><span>Use only the guide and record that fit the confirmed version.</span></li></ol><p class="note">Original question framework, based on the NHTSA decoder scope linked below. Not an identity certificate or condition assessment. Checked 10 November 2026.</p></figure>'
 if slug=='recall-check-to-dealer-record':
  return '<figure class="guide-visual"><figcaption><strong>Follow the question to the appropriate record.</strong></figcaption><ol class="guide-diagram"><li><b>Model campaign?</b><span>Use it to identify the applicability question.</span></li><li><b>VIN result?</b><span>Read the result and the lookup exclusions. An empty result is not a complete history.</span></li><li><b>Open or unclear?</b><span>Ask the manufacturer or dealer for current vehicle-specific instructions.</span></li><li><b>Work claimed complete?</b><span>Request the supporting record; retain unresolved inspection questions.</span></li></ol><p class="note">Original evidence flow. Follow NHTSA and manufacturer guidance linked below. No safety clearance is implied. Checked 10 November 2026.</p></figure>'
 if slug=='car-design-timeline':
  return '<figure class="guide-visual"><figcaption><strong>Four selected milestones, with the event kept explicit.</strong></figcaption><ol class="guide-timeline"><li><b>1966 · Miura</b><span>Public debut, in Lamborghini’s account.</span></li><li><b>1987 · F40</b><span>Model year identified in Ferrari’s museum notes.</span></li><li><b>1990 · original NSX</b><span>Debut described in Honda’s history.</span></li><li><b>1992 · McLaren F1 road car</b><span>Project realised, in McLaren’s account.</span></li></ol><p class="note">Selected manufacturer-archive dates, checked 10 November 2026; links below. These are not verified build dates for the reference photographs or a complete design chronology.</p></figure>'
 if slug=='compare-car-design-briefs':
  return '<figure class="guide-visual"><figcaption><strong>Three different archive facts; three ways to look closer.</strong></figcaption><div class="table-wrap"><table><caption>Selected project features, not a performance ranking</caption><thead><tr><th>Scoped project</th><th>Manufacturer-archive fact</th><th>Original viewing question</th></tr></thead><tbody><tr><th scope="row">Miura</th><td>Transverse mid-mounted V12</td><td>How does the engine packaging relate to the cabin and rear volume?</td></tr><tr><th scope="row">Original NSX</th><td>All-aluminium monocoque</td><td>What does the archive explain that the exterior photo cannot show?</td></tr><tr><th scope="row">McLaren F1 road car</th><td>Carbon-fibre monocoque</td><td>How does the construction story change what you want to inspect in a photograph?</td></tr></tbody></table></div><p class="note">Sources: Lamborghini, Honda and McLaren archives linked below; checked 10 November 2026. Different fact types are retained as such. No dimensions, road test or overall winner is invented.</p></figure>'
 return ''
